  "implementation": "def solve(case):
    items = case['items']
    required = case['required_failure_items']
    unresolved = case['unresolved_without']
    def test(config):
        s = set(config)
        for u in unresolved:
            if u not in s:
                return 'UNRESOLVED'
        for r in required:
            if r not in s:
                return 'PASS'
        return 'FAIL'
    current = items[:]
    tests = 1
    outcome = test(current)
    if outcome != 'FAIL':
        return {'minimal_failure': current, 'outcome': outcome, 'tests': tests}
    granularity = 2
    while granularity <= len(current):
        subsets = partition(current, granularity)
        reduced = False
        for s in subsets:
            tests += 1
            res = test(s)
            if res == 'FAIL':
                current = s
                reduced = True
                break
        if reduced:
            granularity = 2
            continue
        for s in subsets:
            complement = [x for x in current if x not in s]
            tests += 1
            res = test(complement)
            if res == 'FAIL':
                current = complement
                reduced = True
                break
        if reduced:
            granularity = 2
            continue
        granularity = granularity * 2
    tests += 1
    final_outcome = test(current)
    return {'minimal_failure': current, 'outcome': final_outcome, 'tests': tests}

def partition(lst, n):
    size = len(lst)
    base = size // n
    rem = size % n
    result = []
    start = 0
    for i in range(n):
        end = start + base + (1 if i < rem else 0)
        result.append(lst[start:end])
        start = end
    return result"
